/// <summary>
/// MPJ_25205 Customer aging report DCP 15 06 2022
/// </summary>
[ExtensionOf(classStr(CustAgingCalculation))]
final class METCustAgingCalculation_Extension
{
}

Method.Source:
    /// <summary>
    /// Selects and saves detail transactions for customers and vendors that will be aged.
    /// </summary>
    /// <param name = "_agingProcessingTmp">CustVendAgingProcessingTmp</param>
    /// <returns>
    /// A <c>CustVendAgingProcessingDetailsTmp</c> table buffer to which detail transaction data is added.
    /// </returns>
    public CustVendAgingProcessingDetailsTmp metSelectDetailsOfTransactions(CustVendAgingProcessingTmp _agingProcessingTmp)
    {
        CustVendAgingProcessingDetailsTmp   METCustVendAgingProcessingDetailsTmp;
        
        METCustVendAgingProcessingDetailsTmp = this.selectDetailsOfTransactions(_agingProcessingTmp);

        return METCustVendAgingProcessingDetailsTmp;
    }

/// <summary>
/// Assigns buckets to transactions selected for aging.
/// </summary>
/// <param name="_agingProcessingTmp">
/// A <c>CustVendAgingProcessingTmp</c> table containing transaction data.
/// </param>
/// <param name="_agingProcessingDetailsTmp">
/// A <c>CustVendAgingProcessingDetailsTmp</c> table containing transaction details.
/// </param>
/// <remarks>
/// If calculateDetails is false then transaction details are removed from the results.
/// </remarks>
public void metPreProcess(CustVendAgingProcessingTmp _agingProcessingTmp, CustVendAgingProcessingDetailsTmp _agingProcessingDetailsTmp)
{
    this.preProcess(_agingProcessingTmp, _agingProcessingDetailsTmp);
}

    /// <summary>
    /// Selects and saves transactions for customers and vendors that will be aged.
    /// </summary>
    /// <returns>
    /// A <c>CustVendAgingProcessingTmp</c> table buffer to which transaction data is added.
    /// </returns>
    /// <remarks>
    /// <list type = "bullet">
    /// <item>
    ///     <description>Transactions which are opened (not settled) when aging process is run.</description>
    /// </item>
    /// <item>
    ///     <description>Transactions which are opened (not settled) when aging process is run but settled as of today.</description>
    /// </item>
    /// </list>
    /// </remarks>
    public CustVendAgingProcessingTmp metSelectTransactions()
    {
        CustVendAgingProcessingTmp  metCustVendAgingProcessingTmp;

        metCustVendAgingProcessingTmp = this.selectTransactions();

        return metCustVendAgingProcessingTmp;
    }

    /// <summary>
    /// Builds a <c>CustVendTransAging</c> buffer of customers or vendors based on aging process parameters which contains AccountNum, Name and Group.
    /// </summary>
    public void metInsertCustVendData()
    {
        CustVendTransAging metCustomersVendors;

        this.insertCustVendData();

        metCustomersVendors = this.getCustVendTransAging();

    }
